        ["Инструмент", "Отвёртки диэлектрические, ключи, головки", "разборка и сборка узлов"],
        ["Инструмент", "Антистатический браслет, коврик", "защита компонентов от статического электричества"],
        ["Очистка", "Кисти, салфетки, сжатый воздух", "удаление пыли с радиаторов и плат"],
        ["Термоинтерфейсы", "Изопропиловый спирт, термопаста, прокладки", "восстановление теплопередачи"],
